["@Inject
@JMSConnectionFactory("java:/jms/remoteCF")
private JMSContext context;

@Inject
@JMSConnectionFactory("java:/jms/MyConnectionFactory")
private JMSContext consumerContext;

@Resource(lookup = "java:/queue/testQueue")
private Queue queue;

@Override
protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
    resp.setContentType("text/html");
    PrintWriter out = resp.getWriter();
    try {
        out.write("<p>Sending messages to <em>" + queue + "</em></p>");
        out.write("<p>Using context <em>" + context + "</em></p>");
        out.write("<h2>The following messages will be sent to the destination:</h2>");
        for (int i = 0; i < MSG_COUNT; i++) {
            String text = "This is message " + (i + 1);
            context.createProducer().send(queue, text);
            out.write("Message (" + i + "): " + text + "</br>");

            try (JMSConsumer consumer = consumerContext.createConsumer(queue)) {
               TextMessage message = (TextMessage) consumer.receive();
               out.write("Message received (" + i + "): " + message.getText() + "</br>");
            }
        }
    } catch (JMSException e) {
        e.printStackTrace();
    } finally {
        if (out != null) {
            out.close();
        }
    }
}"],"@Inject

["import java.util.*;

import java.util.stream.*;

class Record {
    public String week;
    public String source;
    public String destination;
    public Integer qty;

    Record(String week, String source, String destination, Integer qty) {
        this.week = week;
        this.source = source;
        this.destination = destination;
        this.qty = qty;
    }
}

public class Main {
    public static void main(String[] args) {
        List<Record> records = new ArrayList<>();
        records.add(new Record("w1", "hyd", "kur", 10));
        records.add(new Record("w1", "hyd", "gwd", 20));
        records.add(new Record("w2", "hyd", "kur", 40));
        records.add(new Record("w2", "hyd", "gwd", 10));
        
        
        Map<String, Map<String, Integer>> sums = records
        .stream()
        .collect(Collectors.groupingBy(rec -> rec.week,
            Collectors.groupingBy(rec -> rec.source, 
            Collectors.summingInt(rec->rec.qty))));

